CREATE TABLE IF NOT EXISTS legal_document_version (`document` VARCHAR(32) NOT NULL, version VARCHAR(32) NOT NULL, url VARCHAR(512) NOT NULL, effective_at TIMESTAMP(6) NOT NULL, CONSTRAINT pk_legal_document_version PRIMARY KEY (`document`, version));
CREATE TABLE IF NOT EXISTS legal_document_acceptance (user_id BINARY(16) NOT NULL, `document` VARCHAR(32) NOT NULL, version VARCHAR(32) NOT NULL, accepted_at TIMESTAMP(6) NOT NULL, CONSTRAINT pk_legal_document_acceptance PRIMARY KEY (user_id, `document`, version), CONSTRAINT fk_legal_document_acceptance_user_id__id FOREIGN KEY (user_id) REFERENCES profile(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_legal_document_acceptance_version FOREIGN KEY (`document`, version) REFERENCES legal_document_version(`document`, version) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX IF NOT EXISTS legal_document_acceptance_document_version ON legal_document_acceptance (`document`, version);
